SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'speicher_lage', 'Lage der Speichereinrichtung (unterirdisch: Höchstlasten nach §5.4.5 / Mindestabstand 3 m zu Wurzeln nach §7; oberirdisch: hydrostatischer Druck nach §5.4.5)', 'enum', NULL, false, '§5.4.5, §7', 'Plan 3: Treiber für die bedingten Anforderungen an unterirdische Speichereinrichtungen; CR-13 (abstand_wurzeln_m ≥ 3 auf -04) bedingt zu machen und die Vererbung auf -04 sind STAGED (din16941_2-G-3).', 'imported_unverified', 'Unterirdische Speichereinrichtungen müssen auftretenden Höchstlasten und Belastungen während Betrieb, Einbau, Nutzung und Wartung standhalten. Dies muss entweder durch Berechnung oder Prüfung erfolgen. — Oberirdische Speichereinrichtungen müssen der Wirkung von hydrostatischem Druck ohne übermäßige Verformung standhalten, ohne dass ihre Funktion nachteilig beeinflusst wird. Dies muss entweder durch Berechnung oder Prüfung erfolgen.', 'select_one', NULL, NULL, NULL, '[{"value":"unterirdisch","label_de":"Unterirdische Speichereinrichtung","order_index":0},{"value":"oberirdisch","label_de":"Oberirdische Speichereinrichtung","order_index":1}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
