SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'speichereinrichtungen', 'Speichereinrichtungen (Bezeichnung · Werkstoff · Nennkapazität)', 'json', NULL, false, '§5.4.2, §5.4.3, §5.4.4', 'Plan 3: Zeilen je Speichereinrichtung; Σ Nennkapazität → nennkapazitaet_sum (DIN-EN-16941-2-02-D1), Anzahl → speicher_count (-D2). Ablösung der Skalare nennkapazitaet (an -03 vererbt) und speicher_werkstoff STAGED (din16941_2-D-3 / D-6).', 'imported_unverified', 'Wenn vorgefertigte Teile verwendet werden, muss der Hersteller die Außenmaße, Zugangs- und Anschlussmaße sowie Grenzabmaße (Toleranzen) angeben. Einzelne Speichereinrichtungen dürfen miteinander verbunden werden. — Die Nennkapazität ist das maximale Wasservolumen, das in der Speichereinrichtung zurückgehalten werden kann, und ist vom Hersteller oder Planer anzugeben.', 'register', '{"title":"Speichereinrichtungen für behandeltes Grauwasser","subtitle":"§5.4 — je Speichereinrichtung eine Zeile; Einzelne Speichereinrichtungen dürfen miteinander verbunden werden (§5.4.3); Σ Nennkapazität → nennkapazitaet_sum","add_label":"+ Speichereinrichtung","placement":"section","columns":[{"key":"bezeichnung","label":"Bezeichnung","type":"text","required":true},{"key":"werkstoff","label":"Werkstoff (EN 12566-3)","type":"enum","required":true,"options":["beton","stahl","pvc_u","pe","pp","grp_up"],"option_labels":{"beton":"Beton","stahl":"Stahl","pvc_u":"Polyvinylchlorid (PVC-U)","pe":"Polyethylen (PE)","pp":"Polypropylen (PP)","grp_up":"glasfaserverstärkter Kunststoff (GRP-UP)"}},{"key":"nennkapazitaet_l","label":"Nennkapazität","type":"number","unit":"l","required":true,"min":0,"aria_label":"Nennkapazität der Speichereinrichtung (maximales zurückgehaltenes Wasservolumen, Herstellerangabe)"}],"footer":["nennkapazitaet_sum","speicher_count"],"note":"Wenn vorgefertigte Teile verwendet werden, muss der Hersteller die Außenmaße, Zugangs- und Anschlussmaße sowie Grenzabmaße (Toleranzen) angeben. Einzelne Speichereinrichtungen dürfen miteinander verbunden werden. Die Nennkapazität ist das maximale Wasservolumen, das in der Speichereinrichtung zurückgehalten werden kann, und ist vom Hersteller oder Planer anzugeben. Die Kapazität kann gemessen oder berechnet werden. Die Speichereinrichtung muss aus lichtundurchlässigem Werkstoff bestehen (§5.4.2)."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'speichereinrichtungen') AND w.code = 'DIN-EN-16941-2-02' AND s.code = 'DIN-EN-16941-2';
