SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'nennkapazitaet_sum', 'Nennkapazität gesamt — Summe der verbundenen Speichereinrichtungen (aus dem Register)', 'number', 'l', false, '§5.4.3, §5.4.4', 'Plan 3: Ausgabe der Gleichung DIN-EN-16941-2-02-D1 (sum_rows über speichereinrichtungen.nennkapazitaet_l); das Eingabefeld nennkapazitaet bleibt — Ablösung STAGED (din16941_2-D-3).', 'imported_unverified', 'Wenn vorgefertigte Teile verwendet werden, muss der Hersteller die Außenmaße, Zugangs- und Anschlussmaße sowie Grenzabmaße (Toleranzen) angeben. Einzelne Speichereinrichtungen dürfen miteinander verbunden werden. — Die Nennkapazität ist das maximale Wasservolumen, das in der Speichereinrichtung zurückgehalten werden kann, und ist vom Hersteller oder Planer anzugeben.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
