SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'Y_G_vereinfacht', 'Y_G — Grauwasserertrag nach dem vereinfachten Verfahren (Tabelle A.1: 60 l je Person und Tag · n)', 'number', 'l/d', false, '§6.2.3, Anhang A Tab. A.1', 'Plan 3: Ausgabe der Gleichung DIN-EN-16941-2-03-D5 (n · lookup TABA1 ertrag, anhaltswert); die Übergabe an Y_G / CR-12 unter dem vereinfachten Verfahren ist STAGED (din16941_2-R-1).', 'imported_unverified', 'Für die Berechnung der täglichen Behandlungskapazität des Grauwassersystems muss der durchschnittliche tägliche Ertrag und der Bedarf je Person berücksichtigt werden. Beispiele für typische durchschnittliche tägliche Grauwassererträge und Bedarfsmengen sind in Anhang A (Tabelle A.1) enthalten. — \hline 1 Person & 60 & 35 & 15 & 10 \\', 'derived', NULL, NULL, 'berechnungsverfahren == ''vereinfacht''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'Y_G_vereinfacht') AND w.code = 'DIN-EN-16941-2-03' AND s.code = 'DIN-EN-16941-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'grauwasserquellen_16941', 'Grauwasserquellen (Quelle · Q/V · t · u je Person)', 'json', NULL, false, '§6.2.4.2, Gl. (1); Anhang A Tab. A.2', 'Plan 3: Zeilen je Grauwasserquelle; n · Σ Ertrag je Person → Y_G_rows (DIN-EN-16941-2-03-D1), Anzahl → quellen_count (-D2). Ablösung der 16 Skalare Q_S … u_DW und Umstellung der Gl. (1) STAGED (din16941_2-D-7 / R-1); nur beim differenzierten Verfahren sichtbar.', 'imported_unverified', 'Die folgende Gleichung (1) muss zur Bestimmung des Grauwasserertrags, $Y_{\mathrm{G}}$, in Liter je Tag (l/d), angewendet werden: — Y_{\mathrm{G}}=n \cdot\left(Q_{\mathrm{S}} \cdot t_{\mathrm{S}} \cdot u_{\mathrm{S}}+V_{\mathrm{BT}} \cdot u_{\mathrm{BT}}+Q_{\mathrm{HWB}} \cdot t_{\mathrm{HWB}} \cdot u_{\mathrm{HWB}}+V_{\mathrm{WM}} \cdot u_{\mathrm{WM}}+Q_{\mathrm{KS}} \cdot t_{\mathrm{KS}} \cdot u_{\mathrm{KS}}+V_{\mathrm{DW}}\right.  \tag{1}\\
\left.\cdot u_{\mathrm{DW}}\right)', 'register', '{"title":"Grauwasserquellen (Gl. 1)","subtitle":"je angeschlossener Quelle eine Zeile: Q (l/min) · t (min) · u (1/(p·d)) bei Dusche, Waschbecken und Küchenspüle; V (l) · u (1/(p·d)) bei Badewanne, Waschmaschine und Geschirrspüler — Σ je Person · n → Y_G_rows","add_label":"+ Grauwasserquelle","placement":"section","columns":[{"key":"quelle","label":"Quelle","type":"enum","required":true,"options":["dusche","badewanne","waschbecken","waschmaschine","kuechenspuele","geschirrspueler"],"option_labels":{"dusche":"Dusche (Q_S · t_S · u_S)","badewanne":"Badewanne (V_BT · u_BT)","waschbecken":"Waschbecken (Q_HWB · t_HWB · u_HWB)","waschmaschine":"Waschmaschine (V_WM · u_WM)","kuechenspuele":"Küchenspüle (Q_KS · t_KS · u_KS)","geschirrspueler":"Geschirrspüler (V_DW · u_DW)"}},{"key":"mit_dauer","label":"Term","type":"derived","expr":"lookup(''GL1_LEGENDE'', quelle, ''mit_dauer'')","value_labels":{"0":"V · u","1":"Q · t · u"}},{"key":"hint","label":"Tab. A.2 Größenordnung (Hinweis)","type":"derived","expr":"lookup(''TABA2'', quelle, ''groessenordnung'')"},{"key":"q_or_v","label":"Q bzw. V","type":"number","required":true,"min":0,"aria_label":"Grauwasserabfluss Q in l/min bzw. Wasservolumen V in l je Nutzung"},{"key":"t_x","label":"t","type":"number","unit":"min","required":true,"min":0,"visible_when":"mit_dauer == 1","aria_label":"Dauer je Nutzung in Minuten (Dusche, Waschbecken, Küchenspüle)"},{"key":"u_x","label":"u","type":"number","unit":"1/(p·d)","required":true,"min":0,"aria_label":"Häufigkeit der Nutzung je Person und je Tag"},{"key":"ertrag_row","label":"Ertrag je Person","type":"derived","expr":"if(mit_dauer == 1, q_or_v * t_x * u_x, q_or_v * u_x)","unit":"l/(p·d)"},{"key":"in_hint","label":"Tab. A.2","type":"derived","expr":"if(q_or_v >= lookup(''TABA2'', quelle, ''min'') AND q_or_v <= lookup(''TABA2'', quelle, ''max''), 1, 0)","display":"badge","value_labels":{"0":"außerhalb der Größenordnung nach Tab. A.2 (Hinweis, kein Grenzwert)","1":"innerhalb der Größenordnung nach Tab. A.2"}}],"footer":["Y_G_rows","quellen_count"],"note":"Die folgende Tabelle A. 2 und Tabelle A. 3 enthalten typische Größenordnungen des Wasserverbrauchs zur Bestimmung des Grauwasserertrags und -bedarfs. Die Größenordnungen der Tabelle A.2 sind Hinweise (SR-2), keine Grenzwerte; für das Waschbecken (Q_HWB) druckt die Norm keine Größenordnung. Zur Reduktion des Behandlungsaufwands sollte die Sammlung wie folgt präferiert werden: e) Duschen und Badewannen; f) Handwaschbecken; g) Waschmaschinen; h) Küchenspülen und/oder Geschirrspüler (§6.2.2). Wenn Waschmaschinen Wasser sowohl aus dem Grauwassersystem entnehmen als auch in dieses einspeisen, muss ein geeigneter Behandlungsschritt im System vorgesehen werden und nur geeignetes Grauwasser verwendet werden."}'::jsonb, NULL, 'berechnungsverfahren == ''differenziert''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'grauwasserquellen_16941') AND w.code = 'DIN-EN-16941-2-03' AND s.code = 'DIN-EN-16941-2';
