FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'Y_G_rows') AND w.code = 'DIN-EN-16941-2-03' AND s.code = 'DIN-EN-16941-2';
