\left.\cdot u_{\mathrm{DW}}\right)', 'derived', NULL, NULL, 'berechnungsverfahren == ''differenziert''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
