INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'D_G_vereinfacht', 'D_G — Grauwasserbedarf nach dem vereinfachten Verfahren (Tabelle A.1 je Person und Tag · n, Spalte nach vorgesehene_nutzung: WC 35 / Wäsche 15 / andere 10)', 'number', 'l/d', false, '§6.2.3, Anhang A Tab. A.1', 'Plan 3: Ausgabe der Gleichung DIN-EN-16941-2-03-D6 (n · lookup TABA1 nach der vererbten Einzelauswahl vorgesehene_nutzung — WC und/oder Wäsche sind mit einer Einzelauswahl nicht kombinierbar: din16941_2-J-1); die Übergabe an D_G / CR-12 ist STAGED (din16941_2-R-2).', 'imported_unverified', 'Für die Berechnung der täglichen Behandlungskapazität des Grauwassersystems muss der durchschnittliche tägliche Ertrag und der Bedarf je Person berücksichtigt werden. Beispiele für typische durchschnittliche tägliche Grauwassererträge und Bedarfsmengen sind in Anhang A (Tabelle A.1) enthalten. — \hline 1 Person & 60 & 35 & 15 & 10 \\', 'derived', NULL, NULL, 'berechnungsverfahren == ''vereinfacht''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'D_G_vereinfacht') AND w.code = 'DIN-EN-16941-2-03' AND s.code = 'DIN-EN-16941-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'bedarfsstellen', 'Bedarfsstellen (Bedarfsart · V · u je Person)', 'json', NULL, false, '§6.2.4.3, Gl. (2); Anhang A Tab. A.3', 'Plan 3: Zeilen je Bedarfsart; n · Σ Bedarf je Person + V_misc → D_G_rows (DIN-EN-16941-2-03-D3), Anzahl → bedarfsstellen_count (-D4). Ablösung der Skalare V_T … u_WM_d und Umstellung der Gl. (2) STAGED (din16941_2-D-8 / R-2); V_misc bleibt Skalar (§6.2.4.4); nur beim differenzierten Verfahren sichtbar.', 'imported_unverified', 'Die folgende Gleichung (2) muss für die Bestimmung des Grauwasserbedarfs, $D_{\mathrm{G}}$, in Liter je Tag (l/d) angewendet werden, wenn das behandelte Grauwasser z. B. für die Toiletten- und Urinalspülung, zum Reinigen von Wäsche, zur Gartenbewässerung, für Reinigungsarbeiten usw. genutzt wird. — D_{\mathrm{G}}=n \cdot\left(V_{\mathrm{T}} \cdot u_{\mathrm{T}}+V_{\mathrm{U}} \cdot u_{\mathrm{U}}+V_{\mathrm{WM}} \cdot u_{\mathrm{WM}}\right)+V_{\mathrm{misc}} \tag{2}', 'register', '{"title":"Bedarfsstellen (Gl. 2)","subtitle":"je Bedarfsart eine Zeile (WC-Typ, Urinal, Waschmaschine): V (l je Spülung/Waschvorgang) · u (1/(p·d)) — n · Σ + V_misc → D_G_rows","add_label":"+ Bedarfsstelle","placement":"section","columns":[{"key":"bezeichnung","label":"Bezeichnung (z. B. WC-Typ)","type":"text"},{"key":"bedarf","label":"Bedarfsart","type":"lookup_key","required":true,"lookup":{"table_code":"TABA3"}},{"key":"hint","label":"Tab. A.3 Größenordnung (Hinweis)","type":"lookup_value","lookup":{"table_code":"TABA3","key_column":"bedarf","value":"groessenordnung"}},{"key":"v_x","label":"V","type":"number","unit":"l","required":true,"min":0,"aria_label":"Wasservolumen je Spülung bzw. je Waschvorgang in Liter"},{"key":"u_x","label":"u","type":"number","unit":"1/(p·d)","required":true,"min":0,"aria_label":"Häufigkeit der Nutzung je Person und je Tag"},{"key":"bedarf_row","label":"Bedarf je Person","type":"derived","expr":"v_x * u_x","unit":"l/(p·d)"},{"key":"in_hint","label":"Tab. A.3","type":"derived","expr":"if(v_x >= lookup(''TABA3'', bedarf, ''min'') AND v_x <= lookup(''TABA3'', bedarf, ''max''), 1, 0)","display":"badge","value_labels":{"0":"außerhalb der Größenordnung nach Tab. A.3 (Hinweis, kein Grenzwert)","1":"innerhalb der Größenordnung nach Tab. A.3"}}],"footer":["D_G_rows","bedarfsstellen_count"],"note":"ANMERKUNG Wenn mehr als ein WC-Typ angeschlossen ist, kann der Bedarf für jedes einzelne WC berechnet werden, oder es kann angenommen werden, dass alle WCs gleich benutzt werden. In dem Fall kann ein Standardbedarf für jeden Typ berechnet und für diese Ergebnisse der Durchschnittswert ermittelt werden. \\hline $V_{\\text {misc }}$ & ist das für andere Zwecke erforderliche Wasservolumen (z. B. Gartenbewässerung, Reinigung) in Liter je Tag (l/d). \\\\ Die Größenordnungen der Tabelle A.3 sind Hinweise (SR-2), keine Grenzwerte."}'::jsonb, NULL, 'berechnungsverfahren == ''differenziert''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bedarfsstellen') AND w.code = 'DIN-EN-16941-2-03' AND s.code = 'DIN-EN-16941-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'D_G_rows', 'D_G — Grauwasserbedarf nach Gl. (2) aus dem Register (n · Σ Bedarf je Person + V_misc)', 'number', 'l/d', false, '§6.2.4.3, Gl. (2)', 'Plan 3: Ausgabe der Gleichung DIN-EN-16941-2-03-D3 (n · sum_rows über bedarfsstellen.bedarf_row + V_misc); die verifizierte Gl. (2) über die Skalare bleibt — Umstellung STAGED (din16941_2-R-2).', 'imported_unverified', 'Die folgende Gleichung (2) muss für die Bestimmung des Grauwasserbedarfs, $D_{\mathrm{G}}$, in Liter je Tag (l/d) angewendet werden, wenn das behandelte Grauwasser z. B. für die Toiletten- und Urinalspülung, zum Reinigen von Wäsche, zur Gartenbewässerung, für Reinigungsarbeiten usw. genutzt wird. — D_{\mathrm{G}}=n \cdot\left(V_{\mathrm{T}} \cdot u_{\mathrm{T}}+V_{\mathrm{U}} \cdot u_{\mathrm{U}}+V_{\mathrm{WM}} \cdot u_{\mathrm{WM}}\right)+V_{\mathrm{misc}} \tag{2}', 'derived', NULL, NULL, 'berechnungsverfahren == ''differenziert''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'D_G_rows') AND w.code = 'DIN-EN-16941-2-03' AND s.code = 'DIN-EN-16941-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'bedarfsstellen_count', 'Anzahl der erfassten Bedarfsstellen', 'number', NULL, false, '§6.2.4.3, Gl. (2)', 'Plan 3: Ausgabe der Gleichung DIN-EN-16941-2-03-D4 (count_rows über bedarfsstellen).', 'imported_unverified', 'ANMERKUNG Wenn mehr als ein WC-Typ angeschlossen ist, kann der Bedarf für jedes einzelne WC berechnet werden, oder es kann angenommen werden, dass alle WCs gleich benutzt werden. In dem Fall kann ein Standardbedarf für jeden Typ berechnet und für diese Ergebnisse der Durchschnittswert ermittelt werden.', 'derived', NULL, NULL, 'berechnungsverfahren == ''differenziert''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bedarfsstellen_count') AND w.code = 'DIN-EN-16941-2-03' AND s.code = 'DIN-EN-16941-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'J'), 'bemessungswert_massgebend_calc', 'Maßgebender Bemessungswert — der niedrigste berechnete Wert für den Ertrag oder den Bedarf (min(Y_G, D_G))', 'number', 'l/d', false, '§6.1', 'Plan 3: Ausgabe der Gleichung DIN-EN-16941-2-03-D7 (min über die Gl.-1/2-Ausgaben Y_G und D_G); das Eingabefeld bemessungswert_massgebend (an -02 / -04 vererbt, CR-12) bleibt — Ablösung STAGED (din16941_2-D-5).', 'imported_unverified', 'Für die Gesamtauslegung des Systems muss der niedrigste berechnete Wert für den Ertrag oder den Bedarf verwendet werden. Es wird empfohlen, die Speicherung von behandeltem Grauwasser zu minimieren. Da es im Allgemeinen eine unbegrenzte Nachlieferung von nicht behandeltem Grauwasser gibt, wird normalerweise eine Speicherung in Höhe von bis zu 50 \% des Tagesbedarfs ausreichend sein.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'bemessungswert_massgebend_calc') AND w.code = 'DIN-EN-16941-2-03' AND s.code = 'DIN-EN-16941-2';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'J'), 'speicher_max_50', 'Speicherung in Höhe von bis zu 50 % des Tagesbedarfs (normalerweise ausreichend) — 0,5 · D_G', 'number', 'l', false, '§6.1', 'Plan 3: Ausgabe der Gleichung DIN-EN-16941-2-03-D8 (0,5 · D_G); Vergleich mit der vererbten nennkapazitaet als Warn-Gate STAGED (din16941_2-G-5).', 'imported_unverified', 'Für die Gesamtauslegung des Systems muss der niedrigste berechnete Wert für den Ertrag oder den Bedarf verwendet werden. Es wird empfohlen, die Speicherung von behandeltem Grauwasser zu minimieren. Da es im Allgemeinen eine unbegrenzte Nachlieferung von nicht behandeltem Grauwasser gibt, wird normalerweise eine Speicherung in Höhe von bis zu 50 \% des Tagesbedarfs ausreichend sein.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'speicher_max_50') AND w.code = 'DIN-EN-16941-2-03' AND s.code = 'DIN-EN-16941-2';
