SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'richtwert_spalte', 'Maßgebende Anwendung für die Richtwerte (Spalte der Tabellen D.1 / D.2; Sprühanwendung, wenn Hochdruckreinigung, Gartensprenger oder Autowäsche versorgt werden)', 'enum', NULL, false, '§11, Anhang D Tab. D.1 / D.2', 'Plan 3: Treiber der Richtwert-Füllungen und der Statusableitung im Register probenahmen; die Ableitung aus vorgesehene_nutzung (auf -04 nicht vererbt) plus Sprüh-Flag ist STAGED (din16941_2-D-2 / C-1).', 'imported_unverified', 'Weitere Untersuchungen und die zu untersuchenden Parameter hängen von der Nutzung des Grauwassers ab . — \caption{Tabelle D. 1 — Beispiele für Richtwerte zur bakteriologischen Überwachung nach der Normenreihe BS 8525}', 'select_one', NULL, NULL, NULL, '[{"value":"sprueh","label_de":"Sprühanwendung (Hochdruckreinigung, Gartensprenger und Autowäsche)","order_index":0},{"value":"wc_spuelung","label_de":"WC-Spülung (Anwendung ohne Versprühen)","order_index":1},{"value":"gartenbewaesserung","label_de":"Gartenbewässerung (Anwendung ohne Versprühen)","order_index":2},{"value":"reinigung_waschmaschine","label_de":"Reinigung, d. h. Waschmaschine (Anwendung ohne Versprühen)","order_index":3}]'::jsonb, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
