INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'probenahmen', 'Probenahmen (Datum · Messwerte · Status je Parameter · Ampel)', 'json', NULL, false, '§11; Anhang D Tab. D.1–D.4', 'Plan 3: Zeilen je Stichprobe; Anzahl → probenahmen_count (DIN-EN-16941-2-04-D1), rote / gelbe Proben → probenahmen_rot / probenahmen_gelb (-D2 / -D3), Ampel der letzten Probe → status_letzte_probe (-D4). Ablösung der Einzelmesswerte ecoli_kbe … rest_brom und des manuellen bewertung_status (CR-17, an -05 vererbt) STAGED (din16941_2-D-4 / D-1).', 'imported_unverified', 'Die Probenahmestelle muss im Verteilungssystem für das behandelte Grauwasser eingebaut sein. Alle Proben müssen als Stichproben während der laufenden Behandlung im Grauwassersystem entnommen werden. — Die Ergebnisse aus der bakteriologischen Überwachung können mit Hilfe von Tabelle D. 3 beurteilt werden. Die Ergebnisse der allgemeinen Systemüberwachung sollten mit Hilfe von Tabelle D. 4 beurteilt werden.', 'register', '{"title":"Probenahmen — Prüfung der Wasserqualität (Anhang D)","subtitle":"je Stichprobe eine Zeile; Status je Parameter nach Tabelle D.3 (bakteriologisch: < G grün · G bis 10 G gelb · > 10 G rot) und Tabelle D.4 (System: < G grün · sonst gelb; pH innerhalb des Bereichs grün) gegen die Richtwerte der gewählten Spalte","add_label":"+ Probenahme","placement":"section","columns":[{"key":"datum","label":"Datum der Probenahme","type":"date","required":true},{"key":"ecoli","label":"E. coli","type":"number","unit":"KBE/100 ml","required":true,"min":0,"aria_label":"Escherichia coli in KBE je 100 ml"},{"key":"enterokokken","label":"Int. Enterokokken","type":"number","unit":"KBE/100 ml","required":true,"min":0,"aria_label":"Intestinale Enterokokken in KBE je 100 ml"},{"key":"legionella","label":"Legionella pneumophila","type":"number","unit":"KBE/100 ml","required":true,"min":0,"visible_when":"richtwert_spalte == ''sprueh''","aria_label":"Legionella pneumophila in KBE je 100 ml (Sprühanwendung)"},{"key":"coliforme","label":"Gesamt Coliforme","type":"number","unit":"KBE/100 ml","required":true,"min":0,"aria_label":"Gesamt Coliforme in KBE je 100 ml"},{"key":"truebung","label":"Trübung","type":"number","unit":"NTU","required":true,"min":0,"visible_when":"richtwert_spalte != ''gartenbewaesserung''","aria_label":"Trübung in NTU"},{"key":"ph","label":"pH","type":"number","required":true,"aria_label":"pH-Wert"},{"key":"rest_chlor","label":"Rest-Chlor","type":"number","unit":"mg/l","min":0,"aria_label":"Rest-Chlor in mg/l (wenn verwendet)"},{"key":"rest_brom","label":"Rest-Brom","type":"number","unit":"mg/l","min":0,"aria_label":"Rest-Brom in mg/l (wenn verwendet)"},{"key":"status_ecoli","label":"Status E. coli","type":"derived","expr":"if(lookup(''TABD1'', richtwert_spalte, ''e_coli_text'') == ''Nicht nachweisbar'', if(ecoli == 0, 1, 3), if(lookup(''TABD1'', richtwert_spalte, ''e_coli_text'') == ''N/A'', 0, if(ecoli < lookup(''TABD1'', richtwert_spalte, ''e_coli_g''), 1, if(ecoli <= 10 * lookup(''TABD1'', richtwert_spalte, ''e_coli_g''), 2, 3))))","value_labels":{"0":"n. a. / nicht gemessen","1":"grün","2":"gelb","3":"rot"}},{"key":"status_enterokokken","label":"Status Enterokokken","type":"derived","expr":"if(lookup(''TABD1'', richtwert_spalte, ''enterokokken_text'') == ''Nicht nachweisbar'', if(enterokokken == 0, 1, 3), if(lookup(''TABD1'', richtwert_spalte, ''enterokokken_text'') == ''N/A'', 0, if(enterokokken < lookup(''TABD1'', richtwert_spalte, ''enterokokken_g''), 1, if(enterokokken <= 10 * lookup(''TABD1'', richtwert_spalte, ''enterokokken_g''), 2, 3))))","value_labels":{"0":"n. a. / nicht gemessen","1":"grün","2":"gelb","3":"rot"}},{"key":"status_legionella","label":"Status Legionella","type":"derived","expr":"if(legionella IS NULL, 0, if(lookup(''TABD1'', richtwert_spalte, ''legionella_text'') == ''Nicht nachweisbar'', if(legionella == 0, 1, 3), if(lookup(''TABD1'', richtwert_spalte, ''legionella_text'') == ''N/A'', 0, if(legionella < lookup(''TABD1'', richtwert_spalte, ''legionella_g''), 1, if(legionella <= 10 * lookup(''TABD1'', richtwert_spalte, ''legionella_g''), 2, 3)))))","value_labels":{"0":"n. a. / nicht gemessen","1":"grün","2":"gelb","3":"rot"}},{"key":"status_coliforme","label":"Status Coliforme","type":"derived","expr":"if(lookup(''TABD1'', richtwert_spalte, ''coliforme_text'') == ''Nicht nachweisbar'', if(coliforme == 0, 1, 3), if(lookup(''TABD1'', richtwert_spalte, ''coliforme_text'') == ''N/A'', 0, if(coliforme < lookup(''TABD1'', richtwert_spalte, ''coliforme_g''), 1, if(coliforme <= 10 * lookup(''TABD1'', richtwert_spalte, ''coliforme_g''), 2, 3))))","value_labels":{"0":"n. a. / nicht gemessen","1":"grün","2":"gelb","3":"rot"}},{"key":"status_truebung","label":"Status Trübung","type":"derived","expr":"if(truebung IS NULL, 0, if(lookup(''TABD2'', richtwert_spalte, ''truebung_text'') == ''N/A'', 0, if(truebung < lookup(''TABD2'', richtwert_spalte, ''truebung_max''), 1, 2)))","value_labels":{"0":"n. a. / nicht gemessen","1":"grün","2":"gelb","3":"rot"}},{"key":"status_ph","label":"Status pH","type":"derived","expr":"if(ph >= lookup(''TABD2'', richtwert_spalte, ''ph_min'') AND ph <= lookup(''TABD2'', richtwert_spalte, ''ph_max''), 1, 2)","value_labels":{"0":"n. a. / nicht gemessen","1":"grün","2":"gelb","3":"rot"}},{"key":"status_chlor","label":"Status Rest-Chlor","type":"derived","expr":"if(rest_chlor IS NULL, 0, if(lookup(''TABD2'', richtwert_spalte, ''rest_chlor_text'') == ''N/A'', 0, if(rest_chlor < lookup(''TABD2'', richtwert_spalte, ''rest_chlor_max''), 1, 2)))","value_labels":{"0":"n. a. / nicht gemessen","1":"grün","2":"gelb","3":"rot"}},{"key":"status_brom","label":"Status Rest-Brom","type":"derived","expr":"if(rest_brom IS NULL, 0, if(lookup(''TABD2'', richtwert_spalte, ''rest_brom_text'') == ''0,0'', if(rest_brom <= 0, 1, 2), if(rest_brom < lookup(''TABD2'', richtwert_spalte, ''rest_brom_max''), 1, 2)))","value_labels":{"0":"n. a. / nicht gemessen","1":"grün","2":"gelb","3":"rot"}},{"key":"status_max","label":"Ampel","type":"derived","expr":"max(max(max(status_ecoli, status_enterokokken), max(status_legionella, status_coliforme)), max(max(status_truebung, status_ph), max(status_chlor, status_brom)))","display":"badge","value_labels":{"0":"nicht bewertet","1":"grün — System unter Kontrolle","2":"gelb — erneute Probenahme zur Bestätigung des Ergebnisses und Prüfen des Systembetriebs","3":"rot — Nutzung des Grauwassers ausschließen, bis Problem gelöst ist"}}],"footer":["probenahmen_count","probenahmen_rot","probenahmen_gelb","status_letzte_probe"],"note":"Die Probenahmestelle muss im Verteilungssystem für das behandelte Grauwasser eingebaut sein. Alle Proben müssen als Stichproben während der laufenden Behandlung im Grauwassersystem entnommen werden. Die Ergebnisse aus der bakteriologischen Überwachung können mit Hilfe von Tabelle D. 3 beurteilt werden. Die Ergebnisse der allgemeinen Systemüberwachung sollten mit Hilfe von Tabelle D. 4 beurteilt werden. b Bei Abwesenheit von E. coli, intestinalen Enterokokken und Legionella, falls zutreffend, besteht keine Notwendigkeit, die Anlage außer Betrieb zu nehmen, wenn die gemessenen Werte von Coliformen den Richtwert um das 10fache überschreiten und eine erneute Probenahme zur Bestätigung der Ergebnisse durchgeführt wird. — die Coliformen-Ausnahme (Fußnote b) ist nicht in den Status eingerechnet (rot bleibt; din16941_2-O-2). „Nicht nachweisbar“: jeder Nachweis überschreitet den Richtwert (rot, din16941_2-J-2). Der letzte vollständige Eintrag (Eingabereihenfolge) liefert status_letzte_probe."}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'probenahmen') AND w.code = 'DIN-EN-16941-2-04' AND s.code = 'DIN-EN-16941-2';
