SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'probenahmen_count', 'Anzahl der Probenahmen', 'number', NULL, false, '§11', 'Plan 3: Ausgabe der Gleichung DIN-EN-16941-2-04-D1 (count_rows über probenahmen).', 'imported_unverified', 'Die Probenahmestelle muss im Verteilungssystem für das behandelte Grauwasser eingebaut sein. Alle Proben müssen als Stichproben während der laufenden Behandlung im Grauwassersystem entnommen werden.', 'derived', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
